def priority(item, bins):
    cap = bins.max()
    opn = np.nonzero(bins < cap)[0]
    out = np.zeros(len(bins), dtype=float)
    if len(opn) >= 2:
        order = np.argsort(-bins[opn], kind='stable')
        out[opn[order[1]]] = 1.0
    elif len(opn) == 1:
        out[opn[0]] = 1.0
    else:
        out[np.nonzero(bins == cap)[0][0]] = 1.0
    return out

